import { Sprite, SpriteMaterial, Object3D, Vector3, Euler } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Create container group
  const group = new Object3D();

  // Load texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create sprite material
  const material = new SpriteMaterial({
    map: texture,
    transparent: true,
    depthTest: true,
    depthWrite: false
  });

  // Create sprite (automatically billboards toward camera)
  const sprite = new Sprite(material);
  sprite.position.copy(new Vector3().fromArray(config.position || [3.2, 1, 0.06]));
  sprite.rotation.copy(new Euler().fromArray(config.rotation || [0, 0, 0]));
  sprite.scale.copy(new Vector3().fromArray(config.scale || [1, 1, 1]));

  // Size sprite to atlas region aspect ratio
  const region = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = region.width / region.height;
  // Set base width to 1 unit, scale height accordingly
  sprite.scale.x = 1;
  sprite.scale.y = 1 / aspect;

  group.add(sprite);

  // Apply cinematic primitives (none in this spec, but handle generically)
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    });
  }

  // Attach event handlers (none in this spec)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    material.dispose();
    texture.dispose();
    // Kill any GSAP timelines (none created)
    gsap.killTweensOf(sprite);
  };

  return group;
}
